import 'dart:convert';import 'dart:typed_data';import 'package:cryptography/cryptography.dart';
class PayloadCipher{PayloadCipher(this.key);final SecretKey key;final _cipher=AesGcm.with256bits();Future<String>encrypt(Map<String,dynamic>value)async{final box=await _cipher.encrypt(utf8.encode(jsonEncode(value)),secretKey:key);return base64Encode(Uint8List.fromList([...box.nonce,...box.cipherText,...box.mac.bytes]));}Future<Map<String,dynamic>>decrypt(String encoded)async{final raw=base64Decode(encoded);final nonce=raw.sublist(0,12),mac=raw.sublist(raw.length-16),body=raw.sublist(12,raw.length-16);final clear=await _cipher.decrypt(SecretBox(body,nonce:nonce,mac:Mac(mac)),secretKey:key);return jsonDecode(utf8.decode(clear))as Map<String,dynamic>;}}
